// Car Loan Calculator Logic (guarded)
document.addEventListener('DOMContentLoaded', function () {

  // Guarded calculator initialization: only wire calculator behavior when the page contains the expected elements
  try {
    const calcInputs = document.querySelectorAll('.calc-input');
    const calcBtns = document.querySelectorAll('.calc-btn-row .btn');
    const loanTenureSelectEl = document.querySelector('.select-input');
    const resultAmountEl = document.querySelector('.result-amount');

    const hasCalculator = calcInputs.length >= 4 && calcBtns.length >= 2 && loanTenureSelectEl && resultAmountEl;

    if (hasCalculator) {
      const purchasePriceInput = calcInputs[0];
      const downPaymentInput = calcInputs[1];
      const interestRateInput = calcInputs[3];
      const loanTenureSelect = loanTenureSelectEl;

      // Grab result elements (with fallbacks)
      const resultAmount   = resultAmountEl;
      const resultRowStrong = document.querySelectorAll('.result-row strong');
      const loanAmountEl = resultRowStrong[0] || { textContent: '' };
      const totalInterestEl = resultRowStrong[1] || { textContent: '' };
      const totalPaymentEl = resultRowStrong[2] || { textContent: '' };

      const calculateBtn = calcBtns[0];
      const resetBtn = calcBtns[1];

      function parseNumber(val) {
        return parseFloat((val || '').toString().replace(/,/g, '')) || 0;
      }

      function formatNumber(num) {
        return Number(num).toLocaleString('en-KE', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
      }

      if (calculateBtn) {
        calculateBtn.addEventListener('click', function () {
          const purchasePrice = parseNumber(purchasePriceInput.value);
          const downPayment = parseNumber(downPaymentInput.value);
          const tenureText = (loanTenureSelect && loanTenureSelect.value) || '';
          const annualRate = parseNumber(interestRateInput.value);

          if (!purchasePrice || tenureText === 'Loan Tenure' || !annualRate) {
            alert('Please fill in all fields correctly.');
            return;
          }

          let downPaymentAmount = downPayment;
          if ((downPaymentInput.value || '').includes('%') || downPayment <= 100) {
            downPaymentAmount = (downPayment / 100) * purchasePrice;
          }

          const loanAmount = purchasePrice - downPaymentAmount;
          const months = parseInt(tenureText) || 0;
          const monthlyRate = annualRate / 100 / 12;

          let monthlyPayment;
          if (monthlyRate === 0) {
            monthlyPayment = months ? loanAmount / months : 0;
          } else {
            const factor = Math.pow(1 + monthlyRate, months);
            monthlyPayment = months ? loanAmount * (monthlyRate * factor) / (factor - 1) : 0;
          }

          const totalPayment = monthlyPayment * months;
          const totalInterest = totalPayment - loanAmount;

          resultAmount.innerHTML = `<small>KES </small>${formatNumber(Math.round(monthlyPayment))}`;
          loanAmountEl.textContent = `KES ${formatNumber(Math.round(loanAmount))}`;
          totalInterestEl.textContent = `KES ${formatNumber(Math.round(totalInterest))}`;
          totalPaymentEl.textContent = `KES ${formatNumber(Math.round(totalPayment))}`;
        });
      }

      if (resetBtn) {
        resetBtn.addEventListener('click', function () {
          try { purchasePriceInput.value = ''; } catch (e) {}
          try { downPaymentInput.value = ''; } catch (e) {}
          try { loanTenureSelect.value = 'Loan Tenure'; } catch (e) {}
          try { interestRateInput.value = ''; } catch (e) {}

          resultAmount.innerHTML = `<small>KES </small>0`;
          loanAmountEl.textContent = 'KES 0';
          totalInterestEl.textContent = 'KES 0';
          totalPaymentEl.textContent = 'KES 0';
        });
      }
    }
  } catch (err) {
    // Fail silently — don't block other scripts on the page
    console.warn('Calculator init skipped or failed:', err);
  }

  // Index page search & filters wiring
  const indexSearchWrap = document.querySelector('.search-bar-section');
  if (indexSearchWrap) {
    const idxInput = indexSearchWrap.querySelector('#searchInput');
    const idxSearchBtn = indexSearchWrap.querySelector('.btn-gold');
    const filterBtn = indexSearchWrap.querySelector('.btn-filter');
    const adv = document.querySelector('.advanced-filters');
    if (filterBtn && adv) {
      filterBtn.onclick = () => {
        const shown = adv.style.display !== 'none';
        adv.style.display = shown ? 'none' : 'block';
        filterBtn.textContent = shown ? 'Show More Filters ▽' : 'Hide Filters △';
      };
    }
    if (idxSearchBtn) {
      idxSearchBtn.onclick = () => {
        // Perform in-place filtering on homepage: reuse search inputs and update view
        const q = (idxInput && idxInput.value || '').trim().toLowerCase();
        const min = (document.getElementById('minBudget') && document.getElementById('minBudget').value) || '';
        const max = (document.getElementById('maxBudget') && document.getElementById('maxBudget').value) || '';
        const model = (document.getElementById('filterModel') && document.getElementById('filterModel').value) || '';
        const year = (document.getElementById('filterYear') && document.getElementById('filterYear').value) || '';
        // set search query and filter values globally used by home functions
        setSearch(q);
        // store filter values on window so home pagination/filtering can use them
        window.__homeFilters = { min, max, model: model.toLowerCase(), year: year.toLowerCase() };
        updateHomeView();
      };
    }
  }
});


const CARDS_PER_PAGE = 6; // how many cards per page
let cards = [];
let pageBtns = [];
let prevBtn = null;
let nextBtn = null;
let pagination = null;
let totalPages = 5;
let currentPage = 1;
let searchInput = null;
let searchQuery = '';

function getFilteredCards() {
  return cards.filter(card => {
    // basic text search
    if (searchQuery && !card.textContent.toLowerCase().includes(searchQuery)) return false;
    // advanced filters from homepage
    const f = window.__homeFilters || {};
    if (f.min) {
      const price = extractPriceFromCard(card);
      if (price < Number(f.min)) return false;
    }
    if (f.max) {
      const price = extractPriceFromCard(card);
      if (price > Number(f.max)) return false;
    }
    if (f.model) {
      const model = (card.querySelector('.car-name')?.textContent || '') + ' ' + (card.querySelector('.car-meta-item')?.textContent || '');
      if (!model.toLowerCase().includes(f.model)) return false;
    }
    if (f.year) {
      const y = (card.querySelector('.car-meta-item')?.textContent || '');
      if (!y.toLowerCase().includes(f.year)) return false;
    }
    return true;
  });
}

function extractPriceFromCard(card) {
  try {
    const priceText = (card.querySelector('.car-price')?.textContent || card.textContent || '');
    const m = priceText.replace(/,/g, '').match(/(\d{1,3}(?:\d{3})*)/);
    if (m) return Number(m[0]);
  } catch (e) {}
  return 0;
}

function buildHomePagination() {
  if (!pagination) return;
  const existingPageBtns = Array.from(pagination.querySelectorAll('[data-page]'));
  existingPageBtns.forEach(btn => btn.remove());

  for (let i = 1; i <= totalPages; i++) {
    const btn = document.createElement('div');
    btn.className = 'page-btn';
    btn.dataset.page = String(i);
    btn.textContent = String(i);
    btn.onclick = () => showPage(i);
    pagination.insertBefore(btn, nextBtn || null);
  }

  pageBtns = Array.from(pagination.querySelectorAll('[data-page]'));
  if (prevBtn) prevBtn.onclick = () => showPage(currentPage - 1);
  if (nextBtn) nextBtn.onclick = () => showPage(currentPage + 1);
}

function setSearch(value) {
  searchQuery = (value || '').trim().toLowerCase();
  currentPage = 1;
  updateHomeView();
}

function updateHomeView() {
  const filtered = getFilteredCards();
  totalPages = Math.max(1, Math.ceil(filtered.length / CARDS_PER_PAGE));
  buildHomePagination();
  showPage(currentPage);
  triggerScrollReveal();
}

function showPage(page) {
  const filtered = getFilteredCards();
  totalPages = Math.max(1, Math.ceil(filtered.length / CARDS_PER_PAGE));
  currentPage = Math.max(1, Math.min(page, totalPages));
  const grid = document.querySelector('.section .grid.grid-3');

  cards.forEach(card => card.classList.add('hidden'));
  filtered.forEach((card, index) => {
    const cardPage = Math.floor(index / CARDS_PER_PAGE) + 1;
    if (cardPage === currentPage) {
      card.classList.remove('hidden');
    }
  });

  const noResults = document.querySelector('.no-results');
  if (!filtered.length) {
    if (!noResults && grid) {
      const msg = document.createElement('div');
      msg.className = 'no-results';
      msg.textContent = 'No cars match your search.';
      grid.parentNode.insertBefore(msg, grid.nextSibling);
    }
  } else if (noResults) {
    noResults.remove();
  }

  pageBtns.forEach(btn => {
    btn.classList.toggle('active', Number(btn.dataset.page) === currentPage);
  });

  document.querySelector('.grid-3')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  triggerScrollReveal();
}

function initHomePagination() {
  cards = [...document.querySelectorAll('.section .grid.grid-3 .car-card')];
  pagination = document.querySelector('.pagination');
  prevBtn = document.querySelector('.page-btn[data-prev]');
  nextBtn = document.querySelector('.page-btn[data-next]');
  searchInput = document.querySelector('.search-bar-section .search-input');

  if (searchInput && !searchInput.dataset.homeSearchAttached) {
    searchInput.addEventListener('input', e => setSearch(e.target.value));
    searchInput.dataset.homeSearchAttached = 'true';
  }

  updateHomeView();

  // populate model datalist for homepage
  try {
    const dl = document.getElementById('detailModel');
    if (dl) {
      const set = new Set();
      cards.forEach(card => {
        const nm = (card.querySelector('.car-name')?.textContent || '').trim();
        if (nm) set.add(nm);
      });
      dl.innerHTML = '';
      set.forEach(m => {
        const opt = document.createElement('option'); opt.value = m; dl.appendChild(opt);
      });
    }
  } catch (e) {}

  // Apply filters button (homepage)
  const applyBtn = document.querySelector('.apply-filters');
  if (applyBtn && !applyBtn.dataset.homeAttached) {
    applyBtn.onclick = () => {
      const q = (document.getElementById('searchInput')?.value || '').trim().toLowerCase();
      const min = (document.getElementById('minBudget')?.value) || '';
      const max = (document.getElementById('maxBudget')?.value) || '';
      const model = (document.getElementById('filterModel')?.value) || '';
      const year = (document.getElementById('filterYear')?.value) || '';
      setSearch(q);
      window.__homeFilters = { min, max, model: model.toLowerCase(), year: year.toLowerCase() };
      updateHomeView();
    };
    applyBtn.dataset.homeAttached = '1';
  }

  // popular search tags on homepage (delegated)
  if (!document.body.dataset.poptagAttached) {
    document.addEventListener('click', (e) => {
      const t = e.target;
      if (t.classList && t.classList.contains('pop-tag')) {
        const q = (t.textContent || '').trim();
        const si = document.getElementById('searchInput');
        if (si) si.value = q;
        setSearch(q.toLowerCase());
        window.__homeFilters = {};
        updateHomeView();
      }
    });
    document.body.dataset.poptagAttached = '1';
  }
}

window.refreshHomePagination = initHomePagination;

