// Register service worker for offline caching and enable lazy-loading for images
try {
  // Only register the service worker in non-local environments to avoid
  // SW caching interfering with development and MFA flows on localhost.
  if ('serviceWorker' in navigator && location.hostname !== 'localhost' && location.hostname !== '127.0.0.1') {
    navigator.serviceWorker.register('/sw.js').catch(() => {});
  }
} catch (e) {}

// Apply native lazy-loading to images that look like content images
(function applyLazyLoading(){
  try{
    document.querySelectorAll('img').forEach(img => {
      if (img.loading) return; // browser supports attribute, respect existing
      const src = img.getAttribute('src') || '';
      if (!src || src.startsWith('data:')) return;
      // Skip tiny UI icons (heuristic: file size unknown — skip images with width/height <=48)
      const w = img.width || img.naturalWidth || 0;
      const h = img.height || img.naturalHeight || 0;
      if (w > 48 || h > 48) img.setAttribute('loading', 'lazy');
    });
  }catch(e){}
})();
function updateNavForSession(){
    const session = JSON.parse(localStorage.getItem('naa_session')||'null');
    const loginBtn = document.getElementById('nav-login');
    const signupBtn = document.getElementById('nav-signup');
    const profileBtn = document.getElementById('nav-profile');
    if(session){
      loginBtn.classList.add('hidden');
      signupBtn.classList.add('hidden');
      try { loginBtn.style.display = 'none'; signupBtn.style.display = 'none'; } catch(e) {}
      profileBtn.classList.remove('hidden');
      try { profileBtn.style.display = ''; } catch(e) {}
      profileBtn.title = 'Signed in as ' + session.name;
      profileBtn.href = session.role === 'admin' ? 'users.html' : 'index.html';
    } else {
      loginBtn.classList.remove('hidden');
      signupBtn.classList.remove('hidden');
      try { loginBtn.style.display = ''; signupBtn.style.display = ''; } catch(e) {}
      profileBtn.classList.add('hidden');
      try { profileBtn.style.display = 'none'; } catch(e) {}
    }
  }
  updateNavForSession();

  function prepareAndGoToProforma(){
  const prefill = {};
  document.querySelectorAll('.result-row').forEach(r=>{
    const label = r.querySelector('span'); const val = r.querySelector('strong');
    if(!label||!val) return;
    const key = label.textContent.trim().toLowerCase();
    const num = val.textContent.replace(/[^0-9\.]/g,'');
    if(key.includes('loan')) prefill.price = num;
    if(key.includes('interest')) prefill.rate = num;
  });
  const sel = document.querySelector('.select-input'); if(sel) { const m = sel.value.match(/(\d+)/); if(m) prefill.tenure = m[1]; }
  const carName = document.querySelector('.featured-car-name'); if(carName) prefill.make = carName.textContent.trim().split(' ')[0];
  localStorage.setItem('proforma_prefill', JSON.stringify(prefill));
  const session = JSON.parse(localStorage.getItem('naa_session')||'null');
  if(!session){
    localStorage.setItem('post_login_redirect','proforma-loan-calculator.html');
    window.location.href = 'login.html';
    return;
  }
  window.location.href = 'proforma-loan-calculator.html';
}

const LOGOS = {
  "AUDI": "data:image/png;base64,",
  "BMW": "data:image/png;base64,",
  "FORD": "data:image/png;base64,",
  "INFINITI": "data:image/png;base64,",
  "LEXUS": "data:image/png;base64,",
  "MAZDA": "data:image/png;base64,",
  "MERCEDES": "data:image/png;base64,",
  "MISTUBISHI": "data:image/png;base64,",
  "NISSAN": "data:image/png;base64,",
  "SUBARU": "data:image/png;base64,",
  "SUZUKI": "data:image/png;base64,",
  "TOYOTA": "data:image/png;base64,",
  "VOLKSWAGEN": "data:image/png;base64,",
  "VOLVO": "data:image/png;base64,",
};
const logoNames = Object.keys(LOGOS);
const stage = document.getElementById('stage');

if (stage) {
  function spawn(delay) {
    if (!stage) return;
    const name = logoNames[Math.floor(Math.random() * logoNames.length)];
    const size = 44 + Math.random() * 56;
    const x = Math.random() * (Math.max(0, stage.offsetWidth - size));
    const y = Math.random() * (Math.max(0, stage.offsetHeight - size));
    const dur = 16 + Math.random() * 20;
    const angle = Math.random() * Math.PI * 2;
    const dist = 50 + Math.random() * 100;
    const tx = Math.cos(angle) * dist;
    const ty = Math.sin(angle) * dist;
    const rot = (Math.random() - 0.5) * 16;
    const op = (0.08 + Math.random() * 0.07).toFixed(3);

    const el = document.createElement('div');
    el.className = 'particle';
    el.style.cssText = `left:${x}px;top:${y}px;width:${size}px;height:${size}px;--op:${op};--tx:${tx}px;--ty:${ty}px;--rot:${rot}deg;animation-duration:${dur}s;animation-delay:${delay}s;`;
    const img = document.createElement('img');
    img.src = LOGOS[name];
    el.appendChild(img);
    stage.appendChild(el);
    el.addEventListener('animationend', () => { el.remove(); spawn(Math.random() * 3); });
  }

  for (let i = 0; i < 28; i++) spawn(Math.random() * 15);
}